\title{Good Primes Rule the Denominators:\\
Refuting the ``Only Bad Primes'' Conjecture for Mordell Curves,\\
and an Anti-Factoring Law}
\author{Aristotle}
\date{15 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a Mordell curve $E_N : y^2 = x^3 + N$ over $\Q$ with $N = pq$ a semiprime, it is tempting to
conjecture that the denominators of the $x$-coordinates of the multiples $nP$ of a rational point $P$
are supported on the primes of bad reduction, namely the divisors $\{2,3,p,q\}$ of the discriminant
$\Delta = -432N^2$. Such a statement would make the denominator sequence a factoring oracle. We prove
that the conjecture is false, identify the exact mechanism governing denominator primes, and then prove
a converse law considerably stronger than a mere refutation. First, a \emph{local law}: for a prime
$\ell \ge 5$ with $\ell \nmid N$ one has $\ell \mid \den x(P)$ if and only if $P$ lies in the kernel of
reduction modulo $\ell$, so $\ell \mid \den x(nP)$ exactly when the order of the reduction of $P$ in
$E_N(\F_\ell)$ divides $n$; the witness $N = 55$, $P = (9,28)$ gives $x(2P) = 2601/3136$ with
$3136 = 2^6\cdot 7^2$ and $7 \nmid \Delta$. Second, an \emph{unbounded family of violations}: for every
prime $\ell \ge 5$ and every $t \ge 1$, the modulus $N(\ell,t) = 4\ell^2t^2 - 1 = (2\ell t-1)(2\ell t+1)$
carries the integral point $(1,2\ell t)$ whose doubled $x$-coordinate has $\ell$ in its denominator while
no prime factor of $N(\ell,t)$ does; genuine semiprime instances include $899 = 29\cdot 31$,
$1763 = 41\cdot43$ and $39203 = 197\cdot199$. Third, an \emph{anti-factoring law}: a prime $p \ne 2$
dividing $N$ can divide $\den x(2P)$ only if $P$ meets the singular locus modulo $p$; since integral
points on squarefree moduli never do, for odd squarefree $N$ and any integral point $P$ the entire
doubling orbit $\{2^kP\}$ has $x$-denominators coprime to $N$. The denominator sequence along a doubling
orbit therefore carries no information whatsoever about the factorization of $N$.
\end{abstract}

\noindent\textbf{Keywords:} Mordell curve, elliptic curve denominators, bad reduction, kernel of
reduction, singular locus, elliptic divisibility, integer factorization.

\section{Introduction}

\subsection{The object of study}

Fix a nonzero integer $N$ and consider the \emph{Mordell curve}
\[
  E_N : \quad y^2 = x^3 + N
\]
over $\Q$. It is an elliptic curve of discriminant $\Delta(E_N) = -432N^2$ and $j$-invariant $0$, whose
rational points, together with a point at infinity $O$, form a finitely generated abelian group
$E_N(\Q)$ under the chord-and-tangent law. A prime $\ell$ is a prime of \emph{bad reduction} for $E_N$
if $\ell \mid \Delta$, equivalently if $\ell \in \{2,3\}$ or $\ell \mid N$; all other primes are primes
of \emph{good reduction}.

For a nonzero rational $r$ write $\num r$ and $\den r$ for its numerator and positive denominator in
lowest terms. Given an affine $P \in E_N(\Q)$ and $n \ge 1$ with $nP \ne O$, the \emph{denominator
sequence} of $P$ is $D_n(P) = \den x(nP)$.

\subsection{The conjecture}

If $N = pq$ is a product of two distinct odd primes, the bad primes of $E_N$ are exactly $2,3,p,q$:
both prime factors of $N$ are encoded in the geometry of the curve. This makes the following guess
natural.

\begin{conjecture}[Only bad primes]
For $N = pq$ and $P \in E_N(\Q)$, every prime dividing $D_n(P)$ lies in $\{2,3,p,q\}$.
\end{conjecture}

Were it true, one doubling of a rational point would suffice to factor $N$: compute $D_2(P)$, strip the
powers of $2$ and $3$, and read off $p$ and $q$.

\subsection{Results}

\begin{enumerate}
  \item \textbf{Local law} (Theorem~\ref{thm:local}). For $\ell \ge 5$ prime with $\ell\nmid N$,
    $\ell \mid \den x(P)$ iff $P$ reduces to the identity of $E_N(\F_\ell)$; hence $\ell \mid D_n(P)$ iff
    $\ord(\bar P) \mid n$.
  \item \textbf{Refutation} (Theorem~\ref{thm:counter}). $N = 55$, $P = (9,28)$: $x(2P) = 2601/3136$,
    $3136 = 2^6\cdot 7^2$, and $7 \nmid \Delta = -1306800$.
  \item \textbf{Unbounded family} (Theorem~\ref{thm:family}). For every prime $\ell \ge 5$ and $t \ge 1$,
    with $N = 4\ell^2t^2-1$ and $P = (1,2\ell t)$: $\ell \mid \den x(2P)$ and $\gcd(\den x(2P), N) = 1$.
  \item \textbf{Singular-locus law} (Theorem~\ref{thm:singular}). For $p \ne 2$ with $p \mid N$, if
    $p \mid \den x(2P)$ then $p \mid \den x(P)$ or $P$ reduces mod $p$ to the singular point $(0,0)$.
  \item \textbf{Anti-factoring theorem} (Theorem~\ref{thm:anti}, Corollary~\ref{cor:capstone}). For odd
    squarefree $N$ and any integral point $P$, no prime factor of $N$ divides $\den x(2^kP)$.
\end{enumerate}

\section{Setup: coprime coordinates and duplication}

\begin{lemma}[Coprime parametrization]\label{lem:param}
Let $P = (x,y) \in E_N(\Q)$ be affine. Then there are integers $a,b$ and $e \ge 1$ with
\[
  x = \frac{a}{e^2}, \qquad y = \frac{b}{e^3}, \qquad \gcd(a,e) = \gcd(b,e) = 1,
\]
and consequently $b^2 = a^3 + Ne^6$. In particular $\den x(P) = e^2$, $\den y(P) = e^3$,
$a = \num x(P)$ and $b = \num y(P)$.
\end{lemma}

\begin{proof}[Proof sketch]
Write $x = a/u$, $y = b/v$ in lowest terms; clearing denominators gives $b^2u^3 = v^2(a^3+Nu^3)$.
Comparing $\ell$-adic valuations for each prime $\ell \mid uv$ forces $3v_\ell(u) = 2v_\ell(v)$, so
$u = e^2$ and $v = e^3$ for a positive integer $e$; substituting back gives $b^2 = a^3 + Ne^6$.
\end{proof}

\begin{lemma}[Duplication formula]\label{lem:dup}
Let $P = (x,y) \in E_N(\Q)$ with $y \ne 0$. Then
\[
  x(2P) = \frac{x^4 - 8Nx}{4y^2} = \frac{a\,(a^3 - 8Ne^6)}{4\,b^2e^2}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
The tangent at $P$ has slope $\lambda = 3x^2/(2y)$ and $x(2P) = \lambda^2 - 2x$; substituting
$y^2 = x^3+N$ gives the first expression, and $x = a/e^2$, $y = b/e^3$ the second.
\end{proof}

The second expression need not be in lowest terms; controlling the cancellation is the content of
Sections~\ref{sec:singular} and~\ref{sec:anti}.

\begin{lemma}[Integral bookkeeping]\label{lem:book}
With the notation above,
\[
  \den x(2P) \;\big|\; 4b^2e^2, \qquad \num x(2P) \;\big|\; a\,(a^3 - 8Ne^6).
\]
Equivalently, with $D = \den x(P) = e^2$, the denominator of $x(2P)$ divides $4\,\num(y)^2 D$ and its
numerator divides $\num(x)\bigl(\num(x)^3 - 8ND^3\bigr)$.
\end{lemma}

\begin{proof}[Proof sketch]
If a rational number equals $A/B$ with $B \ne 0$, its reduced denominator divides $B$ and its reduced
numerator divides $A$. Apply this to Lemma~\ref{lem:dup} and use $e^2 = D$, $e^6 = D^3$.
\end{proof}

Lemma~\ref{lem:book} is the engine of the paper: \emph{every prime of $\den x(2P)$ divides $2be$.}

\section{The local law}

Let $\ell \ge 5$ be a prime with $\ell \nmid N$. Reduction gives a group homomorphism
$\rho_\ell : E_N(\Q) \to E_N(\F_\ell)$.

\begin{theorem}[Local law]\label{thm:local}
Let $\ell \ge 5$ be a prime with $\ell \nmid N$ and let $P \in E_N(\Q)$ be affine with coprime
coordinates $(a,b,e)$. Then
\[
  \ell \mid \den x(P) \iff \ell \mid e \iff \rho_\ell(P) = O .
\]
Consequently, if $P$ is integral and $\bar P = \rho_\ell(P)$ has order $m$ in $E_N(\F_\ell)$, then for
all $n \ge 1$ we have $\ell \mid D_n(P)$ if and only if $m \mid n$.
\end{theorem}

\begin{proof}[Proof sketch]
The first equivalence is Lemma~\ref{lem:param}. In projective coordinates $P = (ae : b : e^3)$, and
since $\gcd(b,e) = 1$ the reduction equals $O = (0:1:0)$ exactly when $\ell \mid e$. Finally $\rho_\ell$
is a homomorphism because $\ell$ is a prime of good reduction, so $\rho_\ell(nP) = n\bar P$, which
vanishes iff $m \mid n$.
\end{proof}

\begin{corollary}[Good primes are generic]
Fix an integral point $P$ of infinite order and a good prime $\ell \ge 5$. Then $\ell \mid D_n(P)$ for
all $n$ in the arithmetic progression $\ord(\bar P)\Z_{>0}$. Moreover the union over $n$ of the prime
supports of $D_n(P)$ is infinite, since $\log D_n(P) \sim 2\hat h(P)n^2$ cannot be sustained by finitely
many primes with bounded exponents.
\end{corollary}

Thus divisibility of a denominator by $\ell$ is a statement about the reduction of $P$ modulo $\ell$
and is entirely insensitive to whether $\ell$ divides $\Delta$.

\section{The counterexample}

\begin{theorem}[Refutation]\label{thm:counter}
Let $N = 55 = 5\cdot 11$ and $P = (9,28) \in E_{55}(\Q)$. Then
\[
  x(2P) = \frac{9^4 - 8\cdot55\cdot9}{4(9^3+55)} = \frac{2601}{3136}, \qquad 3136 = 2^6\cdot7^2,
\]
so $7 \mid \den x(2P)$ while $7 \nmid \Delta(E_{55}) = -1306800$. The prime $7$ is a prime of good
reduction, and the ``only bad primes'' conjecture is false.
\end{theorem}

\begin{proof}
$28^2 = 784 = 729+55$, so $P$ lies on $E_{55}$ and $y \ne 0$. Lemma~\ref{lem:dup} gives
$x(2P) = (6561-3960)/(4\cdot784) = 2601/3136$, reduced because $2601 = 3^2\cdot17^2$ is odd and prime to
$7$. Finally $-1306800 = -2^4\cdot3^3\cdot5^2\cdot11^2$.
\end{proof}

Theorem~\ref{thm:local} explains the appearance: $\#E_{55}(\F_7) = 4$ and $\bar P$ has order $2$, so $7$
divides $D_n$ for every even $n$. The first denominators are
\[
  D_1 = 1,\quad D_2 = 2^6\cdot7^2,\quad D_3 = 3^6\cdot13^2\cdot73^2,\quad
  D_4 = 2^8\cdot7^2\cdot827^2\cdot1583^2,\quad D_5 = 5^2\cdot 1785401475301^2,
\]
with local orders $2$ at $7$, $3$ at $13$ and $73$, and $4$ at $827$ and $1583$. The bad prime $5$
occurs at $n = 5$; see \S\ref{sec:disc}.

\section{An unbounded family of violations}

\begin{definition}
For integers $\ell, t \ge 1$ set $N(\ell,t) = 4\ell^2t^2 - 1$, $Y(\ell,t) = 2\ell t$ and
$P_{\ell,t} = (1, Y(\ell,t))$.
\end{definition}

\begin{lemma}[Shape of the family]\label{lem:shape}
For all $\ell,t \ge 1$: (i) $N(\ell,t) = (Y-1)(Y+1)$ with $Y = 2\ell t$, a nontrivial factorization once
$\ell t \ge 1$; (ii) $N(\ell,t)$ is odd; (iii) $Y^2 = 1^3 + N(\ell,t)$, so $P_{\ell,t}$ is an integral
point of $E_{N(\ell,t)}$; (iv) if $\ell \ge 2$ then $\ell \nmid N(\ell,t)$, and if $\ell \ge 5$ is prime
then $\ell \nmid \Delta$, i.e.\ the curve has good reduction at $\ell$; (v) $N(\ell,t) \to \infty$ as
$t \to \infty$.
\end{lemma}

\begin{lemma}[Explicit doubling]\label{lem:famdouble}
With $N = N(\ell,t)$ and $P = P_{\ell,t}$,
\[
  x(2P) = \frac{1-8N}{4(N+1)} = \frac{1-8N}{16\ell^2t^2},
\]
so $\den x(2P)$ divides $16\ell^2t^2$, which is coprime to the odd number $N$.
\end{lemma}

\begin{theorem}[Unbounded maximal violations]\label{thm:family}
Let $\ell \ge 5$ be prime and $t \ge 1$, and put $N = N(\ell,t)$, $P = P_{\ell,t}$. Then $N$ is odd and
factors nontrivially as $(2\ell t-1)(2\ell t+1)$; $E_N$ has good reduction at $\ell$;
$\ell \mid \den x(2P)$; and $\gcd(\den x(2P), N) = 1$, so no prime factor of $N$ divides
$\den x(2P)$. Moreover for every bound $B$ there is $t$ with $N(\ell,t) > B$ satisfying all of the above.
\end{theorem}

\begin{proof}[Proof sketch]
Lemma~\ref{lem:shape} gives the shape and good reduction. For $\ell \mid \den x(2P)$, use the doubling
form of the local law: for $\ell \ge 5$ with $\ell \nmid N$ and $P$ integral, $\ell \mid \den x(2P)$ iff
$\ell \mid y$, and here $y = 2\ell t$. Coprimality of the denominator to $N$ is
Theorem~\ref{thm:preserve} applied to $x = 1$ (numerator and denominator $1$), $N$ odd; alternatively it
follows directly from Lemma~\ref{lem:famdouble}. Unboundedness is Lemma~\ref{lem:shape}(v).
\end{proof}

Choosing $t$ so that $2\ell t \pm 1$ are twin primes yields genuine semiprimes.

\begin{example}
$\ell = 5$, $t = 3$: $N = 899 = 29\cdot31$, $P = (1,30)$, $x(2P) = -799/400$, $400 = 2^4\cdot5^2$.
\end{example}
\begin{example}
$\ell = 7$, $t = 3$: $N = 1763 = 41\cdot43$, $P = (1,42)$, $x(2P) = -1567/784$, $784 = 2^4\cdot7^2$.
\end{example}
\begin{example}
$\ell = 11$, $t = 9$: $N = 39203 = 197\cdot199$, $P = (1,198)$, $x(2P) = -34847/17424$,
$17424 = 2^4\cdot3^2\cdot11^2$.
\end{example}

In each case the prime support of the denominator lies in $\{2,3,\ell\}$ and misses $\{p,q\}$ entirely.
Whether infinitely many $t$ give twin primes is the twin prime conjecture, so
Theorem~\ref{thm:family} is stated with a nontrivial factorization and supplemented by explicit
semiprime instances.

\section{The singular-locus law}\label{sec:singular}

Modulo a prime $p \mid N$ the reduced curve is the cuspidal cubic $y^2 = x^3$ over $\F_p$, whose unique
singular point is $(0,0)$ and whose non-singular locus is isomorphic to $(\F_p,+)$ via
$(x,y) \mapsto x/y$.

\begin{lemma}[Coprimality transfer]\label{lem:transfer}
Let $P$ have coprime coordinates $(a,b,e)$. If $\gcd(a,N) = 1$ then $\gcd(b,N) = 1$ and
$\gcd(a^3 - 8Ne^6, N) = 1$.
\end{lemma}

\begin{proof}[Proof sketch]
Choose $u,v$ with $ua^3 + vN = 1$. Then $ub^2 + (v - ue^6)N = 1$ by $b^2 = a^3+Ne^6$, so $b^2$ and hence
$b$ is coprime to $N$; and $u(a^3-8Ne^6) + (v+8ue^6)N = 1$.
\end{proof}

\begin{theorem}[Doubling preserves coprimality]\label{thm:preserve}
Let $N$ be odd, $P = (x,y) \in E_N(\Q)$ with $y \ne 0$, and suppose $\gcd(\num x, N) = \gcd(\den x, N) = 1$.
Then $\gcd(\num x(2P), N) = \gcd(\den x(2P), N) = 1$.
\end{theorem}

\begin{proof}[Proof sketch]
With coprime coordinates $(a,b,e)$ we have $\gcd(a,N) = \gcd(e^2,N) = 1$, hence $\gcd(b,N)=1$ by
Lemma~\ref{lem:transfer}, and $\gcd(4,N) = 1$ since $N$ is odd. So $4b^2e^2$ is coprime to $N$ and, by
Lemma~\ref{lem:book}, so is $\den x(2P)$. Likewise $\num x(2P)$ divides $a(a^3-8Ne^6)$, both of whose
factors are coprime to $N$.
\end{proof}

\begin{theorem}[Singular-locus law]\label{thm:singular}
Let $p \ne 2$ be a prime dividing $N$ and let $P = (x,y) \in E_N(\Q)$ with $y \ne 0$ and coprime
coordinates $(a,b,e)$. If $p \mid \den x(2P)$ then either $p \mid \den x(P)$, i.e.\ $p \mid e$, or
$p \mid a$ and $p \mid b$, i.e.\ $P$ reduces modulo $p$ to the singular point $(0,0)$ of $y^2 = x^3$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:book}, $p \mid 4b^2e^2$; as $p$ is odd, $p \mid b$ or $p \mid e$. In the second case
we are done. In the first, reducing $b^2 = a^3 + Ne^6$ modulo $p$ and using $p \mid N$, $p \mid b$ gives
$p \mid a^3$, hence $p \mid a$; so $\bar P = (0,0)$.
\end{proof}

The hypothesis $p \ne 2$ cannot be dropped: the factor $4$ in the duplication formula puts $2$ into the
denominator for free.

\section{The anti-factoring theorem}\label{sec:anti}

\begin{lemma}[Integral points on squarefree moduli]\label{lem:sqfree}
Let $N$ be squarefree and $(x,y) \in \Z^2$ with $y^2 = x^3+N$. Then $\gcd(x,N) = 1$.
\end{lemma}

\begin{proof}
If a prime $p$ divides $x$ and $N$, then $p \mid y^2$, so $p \mid y$; hence $p^2 \mid y^2 - x^3 = N$,
contradicting squarefreeness.
\end{proof}

\begin{theorem}[No bad prime after one doubling]\label{thm:onestep}
Let $N$ be squarefree, $(x,y) \in \Z^2$ with $y^2 = x^3+N$ and $y \ne 0$, and $p \ne 2$ a prime dividing
$N$. Then $p \nmid \den x(2P)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:sqfree}, $p \nmid x = \num x(P)$, and $\den x(P) = 1$. Both alternatives of
Theorem~\ref{thm:singular} are excluded.
\end{proof}

\begin{theorem}[Orbit stability]\label{thm:orbit}
Let $N$ be odd and $P \in E_N(\Q)$ with $\gcd(\num x(P), N) = \gcd(\den x(P), N) = 1$. Then for every
$k \ge 0$, if $2^kP$ is affine its $x$-coordinate again has numerator and denominator coprime to $N$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $k$, the step being Theorem~\ref{thm:preserve} applied to $2^{k+1}P = 2^kP + 2^kP$; the
intermediate point is affine with nonzero $y$-coordinate, since otherwise the sum would be $O$.
\end{proof}

\begin{theorem}[Anti-factoring theorem]\label{thm:anti}
Let $N$ be odd and $P \in E_N(\Q)$ with $\num x(P)$ and $\den x(P)$ coprime to $N$. Then for every prime
$p \mid N$ and every $k \ge 0$, $p \nmid \den x(2^kP)$.
\end{theorem}

\begin{corollary}[Capstone]\label{cor:capstone}
Let $N$ be odd and squarefree --- in particular an odd semiprime $N = pq$ --- and let $P$ be any point
of $E_N$ with integer coordinates. Then no prime factor of $N$ divides $\den x(2^kP)$ for any $k \ge 0$.
\end{corollary}

\begin{proof}
Lemma~\ref{lem:sqfree} gives $\gcd(x(P),N) = 1$ and $\den x(P) = 1$; apply Theorem~\ref{thm:anti}.
\end{proof}

For $N = 1763 = 41\cdot43$ and $P = (1,42)$ the denominators of $x(2^kP)$, $k = 0,\dots,4$, are
$1$, $784$, $2652193144304704$, a $66$-digit number and a $266$-digit number, each coprime to $1763$.

\section{Discussion}\label{sec:disc}

\subsection{What a denominator oracle sees}

Good primes are abundant (Theorem~\ref{thm:local}); bad primes are structurally suppressed
(Theorems~\ref{thm:singular} and~\ref{thm:anti}). Hence the doubling-orbit denominator sequence is a
function of $N$ that provably does not reveal the factorization of $N$. Empirically, in a survey of
eleven semiprime moduli with integral base points, the conjectural support condition held in $0\%$ of
cases, the smaller factor $p$ appeared in some denominator in $54.5\%$ of cases and the larger factor
$q$ in none; in an independently generated sample of eleven odd semiprimes with different base points
the figures were $81.8\%$, $9.1\%$ and $0\%$. Visible bad primes always occurred at indices divisible by
the prime in question.

\subsection{Why bad primes surface at index $n = p$}

For $p \mid N$ the non-singular locus of $y^2 = x^3$ over $\F_p$ is isomorphic to $(\F_p,+)$ via
$t = x/y$, and multiplication by $n$ on $(\F_p,+)$ is injective precisely when $p \nmid n$. So a point
whose reduction lies in the smooth locus is killed only at indices divisible by $p$: never for
$n = 2^k$ with $p$ odd, which is Corollary~\ref{cor:capstone} seen locally, and forced at $n = p$, which
is the observed $5^2 \mid D_5$ on $E_{55}$. As a factoring strategy this is worthless: locating the
index $n = p$ presupposes knowing $p$, and $D_p$ has $\Theta(p^2)$ digits by
$\log D_n \sim 2\hat h(P)n^2$.

\subsection{Comparison with the elliptic curve method}

Lenstra's elliptic curve method genuinely factors integers with elliptic curves, and differs in three
decisive ways. (i) It works modulo $N$, not over $\Q$: a factor appears when a modular inversion fails,
so no reduced rational fraction is ever formed and Lemma~\ref{lem:book} does not apply. (ii) It
randomizes the curve, waiting for a group order modulo $p$ that is smooth; here the curve is rigidly
tied to $N$. (iii) It targets a prime of \emph{good} reduction of the random curve, whose group has
order about $p$ and is reachable by smooth multipliers; on $E_N$ the prime $p \mid N$ is bad and its
smooth locus is additive of order exactly $p$, reachable only at indices divisible by $p$. The failure
documented here is therefore a failure of one specific idea --- honest arithmetic over $\Q$ on the
canonical curve of $N$ --- and not of elliptic curves as a factoring tool.

\subsection{Positive content}

Theorem~\ref{thm:local} converts the question ``does $\ell$ divide $D_n(P)$?'' into a finite-field
computation, replacing exact rational arithmetic with $\Theta(n^2)$-digit numbers by $\tilde O(\sqrt\ell)$
field operations. Theorem~\ref{thm:family} generates, for any target good prime and any size, a
semiprime-shaped counterexample on demand. Theorem~\ref{thm:anti} shows the doubling-orbit denominators
take values in the $N$-units.

\section{Algorithms}

\paragraph{Exact rational orbit computation.} Given $N$, $P$ and $n_{\max}$, perform chord-and-tangent
arithmetic over $\Q$ exactly. Since $\log D_n \sim 2\hat h(P)n^2$, computing all $D_n$ with
$n \le n_{\max}$ costs $\tilde O(n_{\max}^3)$ bit operations with $\Theta(n_{\max}^2)$-digit output.

\paragraph{Local prediction of denominator primes.} Given $N$, an integral $P$ and a good prime
$\ell \ge 5$, compute the order $m$ of $\bar P$ in $E_N(\F_\ell)$ by baby-step/giant-step; by
Theorem~\ref{thm:local} the set of indices with $\ell \mid D_n(P)$ is $m\Z_{>0}$. Cost
$\tilde O(\sqrt\ell)$ field operations.

\paragraph{Counterexample family generator.} Given a prime $\ell \ge 5$ and a bound $B$, choose $t$ with
$4\ell^2t^2 - 1 > B$ (optionally with $2\ell t \pm 1$ both prime), set $N = 4\ell^2t^2-1$,
$P = (1,2\ell t)$, and output $x(2P) = (1-8N)/(4(N+1))$. Cost $O(\log B)$ operations plus primality
tests.

\section{Future work}

\begin{conjecture}[$n$-coprime anti-factoring law]
Let $N$ be odd and squarefree, $P$ an integral point of $E_N$, and $n \ge 1$ with $\gcd(n,N) = 1$. Then
$\gcd(D_n(P), N) = 1$; conversely, for each prime $p \mid N$ there are points $P$ with $p \mid D_p(P)$.
\end{conjecture}

\begin{conjecture}[The denominator filtration is a group filtration]
For a prime $\ell \ge 5$ with $\ell \nmid N$ and $m \ge 1$, the set
$E_m(\ell) = \{O\} \cup \{P : \ell^{2m} \mid \den x(P)\}$ is a subgroup of $E_N(\Q)$, and
$v(P+Q) \ge \min(v(P),v(Q))$ for $v(P) = \tfrac12 v_\ell(\den x(P))$; hence
$d(P,Q) = \ell^{-v(P-Q)}$ is an ultrametric making $E_N(\Q)$ a non-archimedean topological group.
\end{conjecture}

\begin{conjecture}[A Zsygmondy law for Mordell denominators]
For every non-torsion integral point $P$ of $E_N$ with $N$ squarefree there is $n_0$ such that for all
$n \ge n_0$ the denominator $D_n(P)$ has a primitive prime divisor $\ell$, dividing no $D_m(P)$ with
$1 \le m < n$; and every such primitive prime is a prime of good reduction for $n$ large.
\end{conjecture}

A fourth, quantitative, direction is to estimate
$\#\{\ell \le X : \ell \mid D_n(P) \text{ for some } n \le n_{\max}\}$, which by
Theorem~\ref{thm:local} reduces to the distribution of local orders in $E_N(\F_\ell)$.

\section{Conclusion}

The ``only bad primes'' conjecture fails in the strongest available sense: good primes occur in the
denominators of $x(nP)$ on $E_N$, as $N = 55$, $P = (9,28)$, $x(2P) = 2601/3136$ shows, and there is an
unbounded semiprime-shaped family on which the doubled denominator is divisible by a prescribed good
prime and by no prime factor of the modulus. The explanation is a local law: a good prime divides a
denominator exactly when the point reduces to the identity in the corresponding finite group. The
converse question has the sharper answer: a bad prime can enter only through the singular point of the
reduced cuspidal curve, which integral points on odd squarefree moduli never reach, so the doubling
orbit's denominators are coprime to $N$ forever.

