"""Algorithm 2: local prediction of denominator primes via finite fields."""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

ModPoint = Optional[Tuple[int, int]]


def add_mod(P: ModPoint, Q: ModPoint, ell: int) -> ModPoint:
    """Chord-and-tangent addition in E_N(F_ell) (N enters through the points)."""
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2 and (y1 + y2) % ell == 0:
        return None
    if P == Q:
        lam = 3 * x1 * x1 % ell * pow(2 * y1 % ell, -1, ell) % ell
    else:
        lam = (y2 - y1) % ell * pow((x2 - x1) % ell, -1, ell) % ell
    x3 = (lam * lam - x1 - x2) % ell
    return (x3, (lam * (x1 - x3) - y1) % ell)


def scalar_mod(n: int, P: ModPoint, ell: int) -> ModPoint:
    """n * P in E_N(F_ell) by double-and-add."""
    R: ModPoint = None
    Q: ModPoint = P
    while n > 0:
        if n & 1:
            R = add_mod(R, Q, ell)
        Q = add_mod(Q, Q, ell)
        n >>= 1
    return R


def group_order(N: int, ell: int) -> int:
    """#E_N(F_ell) by counting square roots of x^3 + N (naive, O(ell))."""
    tally: Dict[int, int] = {}
    for y in range(ell):
        tally[y * y % ell] = tally.get(y * y % ell, 0) + 1
    return 1 + sum(tally.get((x * x * x + N) % ell, 0) for x in range(ell))


def prime_factors(n: int) -> List[int]:
    """Distinct prime factors of n by trial division."""
    out, d = [], 2
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out.append(n)
    return out


def local_order(N: int, x0: int, y0: int, ell: int) -> int:
    """Order of the reduction of the integral point (x0, y0) in E_N(F_ell).

    Uses the group order M = #E_N(F_ell) and divides out prime factors:
    O(log M) group operations after the point count.
    """
    assert ell > 3 and N % ell != 0, "ell must be a prime of good reduction"
    M = group_order(N, ell)
    P: ModPoint = (x0 % ell, y0 % ell)
    assert scalar_mod(M, P, ell) is None, "Lagrange: M kills every point"
    order = M
    for p in prime_factors(M):
        while order % p == 0 and scalar_mod(order // p, P, ell) is None:
            order //= p
    return order


def denominator_indices(N: int, x0: int, y0: int, ell: int,
                        nmax: int) -> List[int]:
    """All n <= nmax with ell | den x(nP), predicted by the local law.

    By the local law, ell divides den x(nP) exactly when the order m of the
    reduction of P divides n; so the answer is the arithmetic progression
    m, 2m, 3m, ...  Cost: O(ell) for the point count plus O(log ell) group
    operations, versus Theta(n^2) digits for the exact rational route.
    """
    m = local_order(N, x0, y0, ell)
    return list(range(m, nmax + 1, m))


if __name__ == "__main__":
    for ell in (7, 13, 17, 19, 73):
        print(ell, local_order(55, 9, 28, ell),
              denominator_indices(55, 9, 28, ell, 20))
